606	func providerHost(provider string) (string, bool) {
607		switch strings.ToLower(strings.TrimSpace(provider)) {
608		case "github":
609			return "github.com", true
610		case "gitlab":
611			return "gitlab.com", true
612		default:
613			return "", false
614		}
615	}
616	
617	// RedactURL removes credentials and query parameters from a URL for safe logging.
618	func RedactURL(rawURL string) string {
619		return gitremote.RedactURL(rawURL)
620	}
621	
622	// RedactURLOrPath is RedactURL for values that may be a remote name or a local
623	// path rather than a URL. See gitremote.RedactURLOrPath.
624	func RedactURLOrPath(target string) string {
